"""Generate the English watch UI fonts from the included OFL Barlow files."""

from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
out = [
    "// Generated by scripts/generate_watch_fonts.py. Barlow: SIL OFL 1.1.",
    "#pragma once",
    "#include <stdint.h>",
    "struct ClockGlyph { uint32_t offset; uint16_t width, height, advance; };",
    "struct ClockFont { const uint8_t *pixels; const ClockGlyph *glyphs; int height; };",
]
characters = "".join(chr(n) for n in range(32, 127))
for name, file, size in [
    ("large", "barlow-semi-condensed/BarlowSemiCondensed-Medium.ttf", 104),
    ("medium", "barlow/Barlow-Regular.ttf", 31),
    ("small", "barlow/Barlow-Regular.ttf", 22),
]:
    font = ImageFont.truetype(str(ROOT / "assets/fonts" / file), size)
    top, bottom = font.getbbox(characters)[1::2]
    pixels, glyphs = [], []
    for char in characters:
        advance = round(font.getlength(char))
        width = max(advance, font.getbbox(char)[2]) + 1
        im = Image.new("L", (width, bottom - top))
        ImageDraw.Draw(im).text((0, -top), char, font=font, fill=255)
        glyphs.append((len(pixels), width, im.height, advance))
        pixels.extend(im.tobytes())
    out += [f"const uint8_t {name}Pixels[] = {{"]
    out.extend(",".join(map(str, pixels[i : i + 64])) + "," for i in range(0, len(pixels), 64))
    out += ["};", f"const ClockGlyph {name}Glyphs[] = {{"]
    out.extend("{" + ",".join(map(str, g)) + "}," for g in glyphs)
    out += ["};", f"const ClockFont {name}Font = {{{name}Pixels,{name}Glyphs,{bottom - top}}};"]
(ROOT / "examples/watch-shell/WatchShell/ClockFonts.h").write_text("\n".join(out) + "\n")
